description:
Write the barrier every exported function wraps its body in:

```cpp
enum Result : int { RESULT_OK = 0, RESULT_INVALID_ARGUMENT = 1, RESULT_OUT_OF_MEMORY = 2, RESULT_FAILED = 3, RESULT_UNKNOWN = 4 };

int barrier(const std::function<void()>& body) noexcept;
```

It runs `body` and returns:

- `RESULT_OK` if it returns normally;
- `RESULT_INVALID_ARGUMENT` for `std::invalid_argument` **and** `std::out_of_range` (both mean the caller passed something bad);
- `RESULT_OUT_OF_MEMORY` for `std::bad_alloc`;
- `RESULT_FAILED` for any other `std::exception`;
- `RESULT_UNKNOWN` for anything else that is thrown, such as an `int`.

Then use it in an exported function:

```cpp
extern "C" int parse_stones(const char* text, int* out) noexcept;
```

It stores `std::stoi(text)` in `*out`. A null `text` or `out` is an invalid argument (throw `std::invalid_argument` inside the barrier). `std::stoi` itself throws `std::invalid_argument` for text that is not a number and `std::out_of_range` for a number too large. A negative number of stones is also invalid. `*out` is only written on success.

starter.solution.cpp:
#include <functional>
#include <new>
#include <stdexcept>
#include <string>

enum Result : int { RESULT_OK = 0, RESULT_INVALID_ARGUMENT = 1, RESULT_OUT_OF_MEMORY = 2, RESULT_FAILED = 3, RESULT_UNKNOWN = 4 };

int barrier(const std::function<void()>& body) noexcept
{
    body();
    return RESULT_OK;
}

extern "C" int parse_stones(const char* text, int* out) noexcept
{
    return barrier([&] {
        *out = std::stoi(text);
    });
}

solution.solution.cpp:
#include <functional>
#include <new>
#include <stdexcept>
#include <string>

enum Result : int { RESULT_OK = 0, RESULT_INVALID_ARGUMENT = 1, RESULT_OUT_OF_MEMORY = 2, RESULT_FAILED = 3, RESULT_UNKNOWN = 4 };

int barrier(const std::function<void()>& body) noexcept
{
    try
    {
        body();
        return RESULT_OK;
    }
    catch (const std::invalid_argument&) { return RESULT_INVALID_ARGUMENT; }
    catch (const std::out_of_range&) { return RESULT_INVALID_ARGUMENT; }
    catch (const std::bad_alloc&) { return RESULT_OUT_OF_MEMORY; }
    catch (const std::exception&) { return RESULT_FAILED; }
    catch (...) { return RESULT_UNKNOWN; }
}

extern "C" int parse_stones(const char* text, int* out) noexcept
{
    return barrier([&] {
        if (!text || !out) throw std::invalid_argument("null argument");
        const int value{ std::stoi(text) };
        if (value < 0) throw std::invalid_argument("negative");
        *out = value;
    });
}

unitTests:
TEST("ok") { CHECK_EQ(barrier([] {}), int(RESULT_OK)); }
TEST("invalid argument and out of range") { CHECK_EQ(barrier([] { throw std::invalid_argument("x"); }), int(RESULT_INVALID_ARGUMENT)); CHECK_EQ(barrier([] { throw std::out_of_range("x"); }), int(RESULT_INVALID_ARGUMENT)); }
TEST("out of memory") { CHECK_EQ(barrier([] { throw std::bad_alloc(); }), int(RESULT_OUT_OF_MEMORY)); }
TEST("other std exceptions") { CHECK_EQ(barrier([] { throw std::runtime_error("x"); }), int(RESULT_FAILED)); CHECK_EQ(barrier([] { throw std::logic_error("x"); }), int(RESULT_FAILED)); }
TEST("anything else") { CHECK_EQ(barrier([] { throw 42; }), int(RESULT_UNKNOWN)); }
TEST("parse a number") { int n = -1; CHECK_EQ(parse_stones("12", &n), int(RESULT_OK)); CHECK_EQ(n, 12); }
TEST("not a number") { int n = 7; CHECK_EQ(parse_stones("stones", &n), int(RESULT_INVALID_ARGUMENT)); CHECK_EQ(n, 7); }
TEST("too large") { int n = 7; CHECK_EQ(parse_stones("99999999999999", &n), int(RESULT_INVALID_ARGUMENT)); CHECK_EQ(n, 7); }
TEST("null pointers") { int n = 0; CHECK_EQ(parse_stones(nullptr, &n), int(RESULT_INVALID_ARGUMENT)); CHECK_EQ(parse_stones("5", nullptr), int(RESULT_INVALID_ARGUMENT)); }
TEST("negative") { int n = 7; CHECK_EQ(parse_stones("-3", &n), int(RESULT_INVALID_ARGUMENT)); CHECK_EQ(n, 7); }

